public sealed class Importer(IDbContextFactory<AppDbContext> factory)
{
    public async Task ImportAsync(IEnumerable<Batch> batches, CancellationToken ct)
    {
        foreach (var batch in batches)
        {
            await using var db = await factory.CreateDbContextAsync(ct); // one context per unit of work
            db.AddRange(batch.Rows);
            await db.SaveChangesAsync(ct);
        }
    }
}

[HttpPut("{id:int}")]
public async Task<IActionResult> Put(int id, UpdateProductDto dto, CancellationToken ct)
{
    var product = await _db.Products.FindAsync([id], ct);
    if (product is null) return NotFound();

    _db.Entry(product).CurrentValues.SetValues(dto);   // matches by property name
    await _db.SaveChangesAsync(ct);                    // UPDATE only changed columns
    return NoContent();
}

