var saved = false;
for (var attempt = 0; !saved && attempt < 3; attempt++)
{
    try { await db.SaveChangesAsync(); saved = true; }
    catch (DbUpdateConcurrencyException ex)
    {
        foreach (var entry in ex.Entries)
        {
            var dbValues = await entry.GetDatabaseValuesAsync();
            if (dbValues is null) throw new ConflictException("Deleted by another user.");

            // merge rule example: keep our Name, take the database Status
            entry.CurrentValues["Status"] = dbValues["Status"];
            entry.OriginalValues.SetValues(dbValues);   // refresh the token, then retry
        }
    }
}

